import { Component, createSignal, Setter } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { BoundBoolean, BoundString } from "#core/ui-next/sandbox/components-browser/components/bound-property.jsx";

export const IconExample: Component = () => {
	const [name, setName] = createSignal("LEADER_BENJAMIN_FRANKLIN");
	const [context, setContext] = createSignal("LEADER_HAPPY");
	const [isUrl, setIsUrl] = createSignal(false);
	const [className, setClassName] = createSignal("size-64");

	return (
		<div class="flex flex-row flex-auto mx-4">
			<ScrollArea class="w-1\/3 m-2 p-2 border border-secondary-3">
				<BoundString
					name="name"
					signal={[name, setName as Setter<string | undefined>]}
				/>
				<BoundString
					name="context"
					signal={[context, setContext as Setter<string | undefined>]}
				/>
				<BoundBoolean
					name="isUrl"
					signal={[isUrl, setIsUrl as Setter<boolean | undefined>]}
				/>
				<BoundString
					name="class"
					signal={[className, setClassName as Setter<string | undefined>]}
				/>
			</ScrollArea>
			<div class="w-2\/3 m-2 p-2 border border-secondary-3 flex flex-col justify-center items-center">
				<div class="flex flex-col my-4 items-center">
					<Icon
						class={className()}
						name={name()}
						context={context()}
						isUrl={isUrl()}
					/>
				</div>
			</div>
		</div>
	);
};
